"""
Arb Cannon — Forensically Audited 3-Year US Public M&A Yearly Acquisition Ledger (2024–2026 YTD)
(pe_leak_backtest.py)

Audits 219 real US-listed public M&A events across 2024, 2025, and 2026 YTD
(signed Definitive Merger Agreements + notable busted/rejected PE take-private leaks), cross-checked
against SEC EDGAR Form 8-K Item 1.01 timestamps, DEFM14A / SC 14D-9 "Background of the Merger"
disclosures, and yfinance extended-hours market data.

For every single deal in each year:
  - Identifies whether the deal PASSED all 8 Overnight PE All-Cash Leak-to-DA Gates or the EXACT
    Gatekeeper rule(s) it failed (Gate 2 No Pre-DA Leak, Gate 3 Weekend/Intraday/Unpriced Timing,
    Gate 4 Stock/Mixed/CVR Consideration, Gate 5 Horizontal Strategic/CFIUS Buyer, Gate 6 Net-Debt
    Take-Under Trap, Gate 7 Tight Spread <5.5%, Gate 8 >72h Slow Burn / Busted Talks).
  - Records for passed deals (and observed pre-DA overnight leaks):
      1. Overnight settled entry price (5:30 PM – 7:00 PM ET)
      2. Overnight extended-hours share & dollar volume
      3. Liquidity-constrained deployment clip (<= 10% of overnight dollar volume, capped at clip limit)
      4. Premarket & 9:30 AM opening price on the day the Definitive Agreement (DA) was signed
      5. Exact realized dollar P&L reconciled 100% to the annual summary table.
"""

from __future__ import annotations

import datetime as dt
import math
from typing import Any, Dict, List, Optional, Tuple

