def _is_friday(date_str: Optional[str]) -> bool:
    if not date_str:
        return False
    try:
        return dt.date.fromisoformat(date_str).weekday() == 4
    except ValueError:
        return False


def enrich_ma_deal(
    raw: Dict[str, Any],
    default_clip_usd: float = 380000.0,
) -> Dict[str, Any]:
    """Compute deployment clip, shares, and realized/unfiltered P&L for a historical M&A record."""
    passed = bool(raw.get("passed_all_gates"))
    entry = raw.get("overnight_entry_price")
    ah_sh = raw.get("overnight_share_volume")
    ah_usd = raw.get("overnight_dollar_volume")
    da_pm = raw.get("da_premarket_price")
    da_open = raw.get("da_open_price")
    stop_open = raw.get("timestop_72h_open_price")
    hrs = raw.get("hours_leak_to_da")

    max_10pct_clip = round(float(ah_usd) * 0.10, 2) if ah_usd is not None and ah_usd > 0 else None
    day_mult = 0.5 if _is_friday(raw.get("leak_date")) else 1.0
    target_cap = round(default_clip_usd * day_mult, 2)

    if passed and entry and entry > 0 and da_open is not None:
        raw_clip = min(target_cap, max_10pct_clip) if max_10pct_clip is not None else target_cap
        shares = math.floor(raw_clip / float(entry))
        deployed_usd = round(shares * float(entry), 2)
        ah_vol_pct = round((deployed_usd / float(ah_usd)) * 100.0, 2) if ah_usd else None
        ret_pct = round(((float(da_open) - float(entry)) / float(entry)) * 100.0, 2)
        pm_ret_pct = (
            round(((float(da_pm) - float(entry)) / float(entry)) * 100.0, 2)
            if da_pm is not None
            else None
        )
        pnl_usd = round(shares * (float(da_open) - float(entry)), 2)
        pm_pnl_usd = (
            round(shares * (float(da_pm) - float(entry)), 2)
            if da_pm is not None
            else None
        )
    else:
        shares = 0
        deployed_usd = 0.0
        ah_vol_pct = None
        ret_pct = None
        pm_ret_pct = None
        pnl_usd = 0.0
        pm_pnl_usd = None

    # Unfiltered 72-Hour Leak P&L: exits at DA Open if DA signed within <=90h (incl. weekend), else at 72h time-stop open
    obs_exit_px: Optional[float] = None
    if raw.get("had_pre_da_leak") and entry and entry > 0:
        if stop_open is not None and (raw.get("da_date") is None or (hrs is not None and hrs > 90)):
            obs_exit_px = float(stop_open)
        elif da_open is not None and (hrs is None or hrs <= 90):
            obs_exit_px = float(da_open)
        elif da_open is not None and stop_open is None:
            obs_exit_px = float(da_open)

    obs_ret_pct: Optional[float] = None
    unfiltered_clip_usd = 0.0
    unfiltered_pnl_usd = 0.0
    if obs_exit_px is not None and entry and entry > 0:
        obs_ret_pct = round(((obs_exit_px - float(entry)) / float(entry)) * 100.0, 2)
        unf_cap = min(default_clip_usd, max_10pct_clip) if max_10pct_clip is not None else default_clip_usd
        unf_shares = math.floor(unf_cap / float(entry))
        unfiltered_clip_usd = round(unf_shares * float(entry), 2)
        unfiltered_pnl_usd = round(unf_shares * (obs_exit_px - float(entry)), 2)

    statuses = raw.get("gate_statuses") or {}
    gate_checks = [
        {
            "id": gid,
            "number": num,
            "title": title,
            "status": statuses.get(gid, "N/A"),
            "passed": statuses.get(gid) == "PASS",
        }
        for gid, num, title in GATE_DEFINITIONS
    ]
    passed_gates_count = sum(1 for g in gate_checks if g["status"] == "PASS")

    deal_px = raw.get("deal_price_per_share")
    gross_disc_pct = (
        round(((float(deal_px) - float(entry)) / float(entry)) * 100.0, 2)
        if deal_px and entry and entry > 0
        else None
    )

    return {
        **raw,
        "max_10pct_ah_clip_usd": max_10pct_clip,
        "deployment_clip_usd": deployed_usd,
        "deployed_shares": shares,
        "clip_pct_of_ah_volume": ah_vol_pct,
        "gross_discount_to_deal_pct": gross_disc_pct,
        "realized_return_pct": ret_pct,
        "premarket_return_pct": pm_ret_pct,
        "realized_pnl_usd": pnl_usd,
        "premarket_pnl_usd": pm_pnl_usd,
        "observed_exit_price": obs_exit_px,
        "observed_leak_return_pct": obs_ret_pct,
        "unfiltered_clip_usd": unfiltered_clip_usd,
        "unfiltered_leak_pnl_usd": unfiltered_pnl_usd,
        "gate_checks": gate_checks,
        "passed_gates_count": passed_gates_count,
        "total_gates_count": len(gate_checks),
    }


def _deal_sort_key(d: Dict[str, Any]) -> Tuple[int, int, str, float]:
    has_obs = 0 if (d.get("had_pre_da_leak") and d.get("overnight_entry_price") is not None) else 1
    return (
        0 if d.get("passed_all_gates") else 1,
        has_obs,
        d.get("da_date") or d.get("leak_date") or "9999-99-99",
        -float(d.get("deal_ev_billions") or 0.0),
    )


def run_pe_leak_backtest(
    default_clip_usd: float = 380000.0,
    capital_pool_usd: float = 400000.0,
) -> Dict[str, Any]:
    """
    Run the complete 2024–2026 YTD US Public M&A Yearly Breakdown & 8-Gate Backtest.
    Every dollar in `annual_pnl_table` reconciles directly to the individual deal rows.
    """
    enriched = [enrich_ma_deal(r, default_clip_usd=default_clip_usd) for r in HISTORICAL_MA_DEALS_2024_2026]

    years = ("2024", "2025", "2026 YTD")
    annual_pnl_table: List[Dict[str, Any]] = []
    yearly_breakdown: List[Dict[str, Any]] = []

    for yr in years:
        yr_deals = sorted([d for d in enriched if d["year"] == yr], key=_deal_sort_key)
        passed_deals = [d for d in yr_deals if d["passed_all_gates"]]
        failed_deals = [d for d in yr_deals if not d["passed_all_gates"]]
        signed_das = [d for d in yr_deals if d.get("da_date") is not None]
        busted_leaks = [d for d in yr_deals if d.get("da_date") is None]
        leaked_deals = [d for d in yr_deals if d.get("had_pre_da_leak")]
        tradable_leaks = [d for d in yr_deals if d.get("unfiltered_clip_usd", 0.0) > 0]

        filtered_pnl = round(sum(d["realized_pnl_usd"] for d in passed_deals))
        unfiltered_pnl = round(sum(d["unfiltered_leak_pnl_usd"] for d in yr_deals))
        deployed_cap = round(sum(d["deployment_clip_usd"] for d in passed_deals))
        sgov_usd = IDLE_SGOV_BY_YEAR[yr]

        gate_fail_counts: Dict[str, int] = {}
        for d in failed_deals:
            fg = d.get("primary_failed_gate") or "OTHER"
            gate_fail_counts[fg] = gate_fail_counts.get(fg, 0) + 1

        row_summary = {
            "year": yr,
            "total_deals": len(yr_deals),
            "signed_da_count": len(signed_das),
            "busted_leak_count": len(busted_leaks),
            "pre_da_leak_count": len(leaked_deals),
            "tradable_leak_count": len(tradable_leaks),
            "passed_count": len(passed_deals),
            "failed_count": len(failed_deals),
            "deployed_capital_usd": deployed_cap,
            "filtered_strategy_usd": filtered_pnl,
            "unfiltered_all_leaks_usd": unfiltered_pnl,
            "idle_sgov_usd": sgov_usd,
            "gate_failure_counts": gate_fail_counts,
        }
        annual_pnl_table.append(row_summary)
        yearly_breakdown.append({
            **row_summary,
            "deals": yr_deals,
        })

    all_passed = [d for d in enriched if d["passed_all_gates"]]
    passed_wins = [d for d in all_passed if (d.get("realized_pnl_usd") or 0.0) > 0]
    win_rate_pct = round((len(passed_wins) / len(all_passed)) * 100.0, 1) if all_passed else 0.0
    avg_spread_pct = (
        round(sum(float(d["realized_return_pct"]) for d in all_passed) / len(all_passed), 2)
        if all_passed
        else 0.0
    )
    avg_clip_usd = (
        round(sum(float(d["deployment_clip_usd"]) for d in all_passed) / len(all_passed))
        if all_passed
        else round(default_clip_usd)
    )

    total_deals_count = len(enriched)
    total_signed_das = sum(r["signed_da_count"] for r in annual_pnl_table)
    total_busted = sum(r["busted_leak_count"] for r in annual_pnl_table)
    total_leaks = sum(r["pre_da_leak_count"] for r in annual_pnl_table)
    cum_filtered = sum(r["filtered_strategy_usd"] for r in annual_pnl_table)
    cum_unfiltered = sum(r["unfiltered_all_leaks_usd"] for r in annual_pnl_table)
    cum_sgov = sum(r["idle_sgov_usd"] for r in annual_pnl_table)
    cum_deployed = sum(r["deployed_capital_usd"] for r in annual_pnl_table)

    overall_gate_failures: Dict[str, int] = {}
    for d in enriched:
        if not d["passed_all_gates"]:
            fg = d.get("primary_failed_gate") or "OTHER"
            overall_gate_failures[fg] = overall_gate_failures.get(fg, 0) + 1

    return {
        "period_label": (
            f"2024–2026 YTD ({total_deals_count} M&A Events Audited: "
            f"{total_signed_das} Signed DAs + {total_busted} Busted PE Leaks)"
        ),
        "total_ma_events_audited": total_deals_count,
        "total_signed_das": total_signed_das,
        "total_busted_pe_leaks": total_busted,
        "total_leak_events": total_leaks,
        "qualified_passed_count": len(all_passed),
        "qualified_wins": len(passed_wins),
        "qualified_losses": len(all_passed) - len(passed_wins),
        "filtered_win_rate_pct": win_rate_pct,
        "sun_mon_tue_named_buyer_win_rate_pct": win_rate_pct,
        "avg_net_spread_captured_pct": avg_spread_pct,
        "target_capital_pool_usd": round(capital_pool_usd),
        "default_clip_usd": round(default_clip_usd),
        "historical_avg_clip_usd": avg_clip_usd,
        "clip_sizing_rule": "<= 10% of settled extended-hours dollar volume (capped at $380,000 clip; 50% on Fridays)",
        "idle_parking_vehicle": "$SGOV (0–3 Month US Treasury ETF, ~4.25%–5.15% annualized risk-free yield)",
        "qualified_trade_frequency": f"{len(all_passed)} qualified setups out of {total_deals_count} audited M&A events (2024–2026 YTD)",
        "avg_hold_time": (
            f"{round(sum(float(d['hours_leak_to_da']) for d in all_passed if d.get('hours_leak_to_da')) / max(1, len(all_passed)), 1)} Hours (Leak Entry -> Premarket / 9:30 AM DA Open)"
        ),
        "realized_annual_net_dollar_expectation": (
            f"+${cum_filtered:,} realized trade alpha (+${cum_sgov:,} idle $SGOV yield = +${cum_filtered + cum_sgov:,} 3-yr total)"
        ),
        "cumulative_deployed_capital_usd": cum_deployed,
        "cumulative_3yr_filtered_usd": cum_filtered,
        "cumulative_3yr_unfiltered_usd": cum_unfiltered,
        "cumulative_3yr_sgov_usd": cum_sgov,
        "overall_gate_failure_counts": overall_gate_failures,
        "annual_pnl_table": annual_pnl_table,
        "yearly_breakdown": yearly_breakdown,
        "historical_deals": enriched,
    }
